WITH scored AS (SELECT id, customer_id, account_type, balance, opened_date, status, SUM(balance) OVER (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_balance, LEAD(balance, 2) OVER (PARTITION BY customer_id ORDER BY balance, id) AS next_balance, NTILE(10) OVER (PARTITION BY customer_id ORDER BY balance, id) AS balance_bucket, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY balance, id) AS seq_no, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY balance, id) AS seq_no_2 FROM accounts) SELECT id, customer_id, account_type, balance, status, cumulative_balance, next_balance, balance_bucket, seq_no_2 FROM scored ORDER BY status;
